"""Real browser checks for device-only v2 workspace; no paid model calls."""
import os, json, base64, subprocess
from pathlib import Path
from playwright.sync_api import sync_playwright, expect
base=os.environ.get('DIRECTOR_TEST_URL','http://127.0.0.1:3200')
out=Path('test-results'); out.mkdir(exist_ok=True)
clip=out/'qa-reference.mp4'
subprocess.run(['ffmpeg','-y','-f','lavfi','-i','testsrc2=size=640x360:rate=24','-t','3','-c:v','libx264','-pix_fmt','yuv420p',str(clip)],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ.get('DIRECTOR_CHROMIUM_PATH','/usr/bin/chromium'),args=['--no-sandbox','--disable-dev-shm-usage'])
 c=b.new_context(viewport={'width':1440,'height':1000},ignore_https_errors=False)
 page=c.new_page(); page.set_default_timeout(12000); errors=[]; console=[]; failed=[]; page.on('console',lambda m: console.append({'type':m.type,'text':m.text}) if m.type in ['error','warning'] else None); page.on('response',lambda r: failed.append({'status':r.status,'url':r.url}) if r.status>=400 else None); page.on('pageerror',lambda e:errors.append(str(e)))
 page.goto(base); page.locator('#premise').fill('A station keeper finds a letter from tomorrow.'); page.locator('#start-device').click()
 expect(page.locator('.workspace.briefing')).to_be_visible()
 page.locator('#brief-project-settings').click(); page.locator('.brief-details>summary').click(); page.locator('#brief-form input[name=title]').fill('Tomorrow’s Letter'); page.locator('#brief-form button[type=submit]').click()
 expect(page.locator('.film-brief-summary h2')).to_have_text('Tomorrow’s Letter')
 page.screenshot(path=str(out/'v2-brief-desktop.png'),full_page=True)
 page.locator('#approve-direction').click(); page.locator('#continue-direction').click(); expect(page.locator('#screenplay-workspace')).to_be_visible(); page.locator('.legacy-story>summary').click(); expect(page.locator('#story-form')).to_be_visible()
 page.locator('[name=treatment]').fill('A keeper opens a letter, rejects its warning, and chooses to wait for the last train.')
 page.locator('[name=scenes]').fill('INT. STATION — NIGHT: the letter arrives.\nEXT. PLATFORM — DAWN: the keeper waits.')
 page.locator('#story-form button[type=submit]').click(); page.locator('#approve-story').click()
 page.locator('[data-stage=storyboard]').click(); page.locator('#add-shot').click()
 page.locator('#shot-form [name=title]').fill('The last platform'); page.locator('#shot-form [name=constraints]').fill('Keep the red coat and dawn lighting.')
 page.locator('#shot-form button[type=submit]').click()
 page.locator('[data-stage=production]').click(); expect(page.locator('.workspace.production')).to_be_visible()
 page.locator('#viewer-add').click(); page.locator('#upload-file').set_input_files({'name':'reference.png','mimeType':'image/png','buffer':base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=')})
 page.locator('#upload-form button[type=submit]').click(); expect(page.locator('#studio-still')).to_be_visible()
 first_image=page.locator('#studio-still').get_attribute('src')
 page.locator('[data-stage=cast]').click()
 page.locator('#cast-upload').click(); page.locator('#upload-scope').select_option('project'); page.locator('#upload-role').select_option('visual_style')
 page.locator('#upload-file').set_input_files({'name':'alternate-reference.png','mimeType':'image/png','buffer':base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=')})
 page.locator('#upload-form button[type=submit]').click()
 page.locator('.panel').filter(has=page.get_by_role('heading',name='alternate-reference.png',exact=True)).locator('[data-use-media]').click()
 page.locator('[data-stage=production]').click(); expect(page.locator('#studio-still')).to_be_visible(); assert page.locator('#studio-still').get_attribute('src')!=first_image
 page.locator('#rail-upload').click(); page.locator('#upload-scope').select_option('shot'); page.locator('#upload-role').select_option('shot_reference'); page.locator('#upload-file').set_input_files(str(clip)); page.locator('#upload-form button[type=submit]').click()
 page.locator('[data-stage=cast]').click()
 page.locator('.panel').filter(has=page.get_by_role('heading',name='qa-reference.mp4',exact=True)).locator('[data-use-media]').click()
 page.locator('[data-stage=production]').click()
 expect(page.locator('#studio-player')).to_be_visible(); page.locator('#player-toggle').click()
 print('Checking playback',flush=True); page.wait_for_function('()=>document.querySelector("#studio-player").currentTime > 0.3')
 page.locator('#player-toggle').click(); assert page.locator('#studio-player').evaluate('(v)=>v.paused')
 page.locator('#player-seek').evaluate('(e)=>{e.value=600;e.dispatchEvent(new Event("input"))}')
 print('Checking playback',flush=True); page.wait_for_function('()=>document.querySelector("#studio-player").currentTime > 1.5')
 page.locator('#composer-input').fill('Hold the final frame longer.'); page.locator('.send').click()
 expect(page.locator('#messages')).to_contain_text('Hold the final frame longer.')
 page.reload(); expect(page.locator('#studio-player')).to_be_visible(); expect(page.locator('#messages')).to_contain_text('Hold the final frame longer.')
 page.screenshot(path=str(out/'v2-production-desktop.png'),full_page=True)
 page.locator('#projects-button').click(); expect(page.locator('#project-list')).to_contain_text('Tomorrow’s Letter'); page.locator('[data-project]').first.click(); expect(page.locator('#studio-player')).to_be_visible()
 page.locator('#cloud-save').click(); expect(page.locator('#toast')).to_contain_text('not connected')
 page.locator('[data-stage=export]').click()
 expect(page.locator('.shot-details-bar')).to_contain_text('Hosted export is not connected')
 with page.expect_download() as d: page.locator('#download-draft').click()
 assert d.value.suggested_filename.endswith('.json')
 page.set_viewport_size({'width':390,'height':844}); page.reload(); expect(page.locator('#mobile-director')).to_be_visible()
 assert page.evaluate('document.documentElement.scrollWidth <= innerWidth'), 'horizontal overflow'
 page.locator('#mobile-director').click(); expect(page.locator('#director.open')).to_be_visible(); page.locator('#close-director').click()
 page.locator('#mobile-project').click(); expect(page.locator('#rail.open')).to_be_visible();  page.locator('[data-stage=brief]').click()
 expect(page.locator('#compact-brief')).to_be_visible(); assert page.locator('textarea:visible').count()<=1; page.locator('#mobile-director').click(); page.locator('.brief-details>summary').click(); expect(page.locator('#brief-form')).to_be_visible()
 page.screenshot(path=str(out/'v2-brief-mobile-viewport.png'),full_page=True)
 # Fresh first-use entry: attachments, removal, invalid input recovery and persistence.
 for width,height in [(1440,1000),(390,844)]:
  fresh=b.new_context(viewport={'width':width,'height':height});entry=fresh.new_page();entry.set_default_timeout(7000)
  entry.on('pageerror',lambda e:errors.append(str(e)))
  entry.goto(base);expect(entry.get_by_role('heading',name='What do you want to create?')).to_be_visible()
  entry.locator('#premise').fill('A product ad using my reference image.')
  upload=entry.get_by_role('button',name='Upload files',exact=True)
  with entry.expect_file_chooser() as chooser:upload.click()
  chooser.value.set_files({'name':'product.png','mimeType':'image/png','buffer':base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=')})
  expect(entry.locator('#welcome-attachments')).to_contain_text('product.png')
  entry.get_by_role('button',name='Advertisement',exact=True).click();expect(entry.locator('#welcome-attachments')).to_contain_text('product.png')
  entry.get_by_role('button',name='Remove product.png',exact=True).click();expect(entry.locator('#welcome-attachments')).not_to_contain_text('product.png')
  entry.locator('#welcome-file').set_input_files({'name':'bad.html','mimeType':'text/html','buffer':b'<html>unsupported</html>'})
  expect(entry.locator('#welcome-error')).to_contain_text('supported');expect(entry.locator('#premise')).to_have_value('A product ad using my reference image.')
  entry.locator('#welcome-file').set_input_files({'name':'product.png','mimeType':'image/png','buffer':base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII=')})
  entry.locator('#start-device').click();expect(entry.locator('#rail')).to_contain_text('product.png');entry.reload();expect(entry.locator('#rail')).to_contain_text('product.png')
  entry.locator('#brief-project-settings').click();expect(entry.locator('#close-director')).to_be_visible();entry.locator('#close-director').click();expect(entry.locator('#director.open')).not_to_be_visible();expect(entry.locator('#brief-project-settings')).to_be_focused()
  if width<1000:entry.locator('#mobile-project').click()
  entry.locator('[data-stage=production]').click()
  if width<1000:entry.locator('#mobile-project').click()
  expect(entry.locator('[data-stage=edit]')).to_be_visible();entry.locator('[data-stage=edit]').click()
  if width<1000:entry.locator('#mobile-project').click()
  entry.locator('[data-stage=export]').click()
  if width<1000:entry.locator('#mobile-project').click()
  entry.locator('[data-stage=brief]').click()
  entry.screenshot(path=str(out/f'entry-ux-brief-{width}.png'),full_page=True)
  assert entry.evaluate('document.documentElement.scrollWidth<=innerWidth')
  fresh.close()
 assert not errors, errors
 assert not console, console
 assert not failed, failed
 (out/'v2-workspace-results.json').write_text(json.dumps({'url':base,'passed':['brief editing','story version and approval','shot editing','image preview and alternate image selection','video playback pause seek','draft and media reload persistence','direction notes and saved-project picker','truthful cloud gate','draft JSON download','390px viewport drawers and overflow'],'pageErrors':errors,'console':console,'httpErrors':failed,'physicalMobileTested':False},indent=2))
 print('PASS: v2 device workspace flows; no page exceptions. Physical mobile untested.')
 b.close()
